import{_ as a}from"./chunks/microstrain_3dm_cv7_hbk.CXpemUxF.js";import{_ as r,o as i,c as n,al as t}from"./chunks/framework.7vp1BMOE.js";const u=JSON.parse('{"title":"MicroStrain (INS, IMU, VRU, AHRS)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/sensor/microstrain.md","filePath":"zh/sensor/microstrain.md"}'),o={name:"zh/sensor/microstrain.md"};function l(c,e,s,_,d,f){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="microstrain-ins-imu-vru-ahrs" tabindex="-1">MicroStrain (INS, IMU, VRU, AHRS) <a class="header-anchor" href="#microstrain-ins-imu-vru-ahrs" aria-label="Permalink to &quot;MicroStrain (INS, IMU, VRU, AHRS)&quot;">​</a></h1><p>MicroStrain by HBK provides high-performance inertial sensors engineered for reliability and precision in challenging environments. Widely used across industries like aerospace, robotics, industrial automation, and research, MicroStrain sensors are optimized for real-time, accurate motion tracking and orientation data.</p><p><img src="'+a+'" alt="CV7"></p><p>The driver currently supports the following hardware:</p><ul><li><a href="https://www.hbkworld.com/en/products/transducers/inertial-sensors/vertical-reference/3dm-cv7-ar" target="_blank" rel="noreferrer"><code>MicroStrain CV7-AR</code></a>: Inertial Measurement Unit (IMU) and Vertical Reference Unit (VRU)</li><li><a href="https://www.hbkworld.com/en/products/transducers/inertial-sensors/attitude-and-heading/3dm-cv7-ahrs" target="_blank" rel="noreferrer"><code>MicroStrain CV7-AHRS</code></a>: Inertial Measurement Unit (IMU) and Attitude Heading Reference System (AHRS)</li><li><a href="https://www.hbkworld.com/en/products/transducers/inertial-sensors/navigation/3dm-cv7-ins" target="_blank" rel="noreferrer"><code>MicroStrain CV7-INS</code></a>: Inertial Measurement Unit (IMU) and Inertial Navigation System (INS).</li><li><a href="https://www.hbkworld.com/en/products/transducers/inertial-sensors/navigation/3dm-cv7-gnss-ins" target="_blank" rel="noreferrer"><code>MicroStrain CV7-GNSS/INS</code></a>: Inertial Measurement Unit (IMU) and Inertial Navigation System (INS) combined with dual multiband (GNSS) receivers.</li></ul><p>PX4 can use these sensors to provide raw IMU data for EKF2 or to replace EKF2 as an external INS. For more information, including user manuals and datasheets, please refer to the sensors product page.</p><h2 id="购买渠道" tabindex="-1">购买渠道 <a class="header-anchor" href="#购买渠道" aria-label="Permalink to &quot;购买渠道&quot;">​</a></h2><p>MicroStrain sensors can be purchased through HBK&#39;s official <a href="https://www.hbkworld.com/en/products/transducers/inertial-sensors" target="_blank" rel="noreferrer">MicroStrain product page</a> or through authorized distributors globally. For large orders, custom requirements, or technical inquiries, reach out directly to <a href="https://www.hbkworld.com/en/contact-us" target="_blank" rel="noreferrer">sales</a></p><h2 id="硬件安装" tabindex="-1">硬件安装 <a class="header-anchor" href="#硬件安装" aria-label="Permalink to &quot;硬件安装&quot;">​</a></h2><h3 id="布线" tabindex="-1">布线 <a class="header-anchor" href="#布线" aria-label="Permalink to &quot;布线&quot;">​</a></h3><p>Connect the main UART port of the MicroStrain sensor to any unused serial port on the flight controller. This port needs to be specified while starting the device.</p><h3 id="mounting" tabindex="-1">Mounting <a class="header-anchor" href="#mounting" aria-label="Permalink to &quot;Mounting&quot;">​</a></h3><p>The MicroStrain sensor can be mounted in any orientation. The default coordinate system uses X for the front, Y for the right, and Z for down, with directions marked on the device.</p><h2 id="firmware-configuration" tabindex="-1">Firmware Configuration <a class="header-anchor" href="#firmware-configuration" aria-label="Permalink to &quot;Firmware Configuration&quot;">​</a></h2><h3 id="px4-配置" tabindex="-1">PX4 配置 <a class="header-anchor" href="#px4-配置" aria-label="Permalink to &quot;PX4 配置&quot;">​</a></h3><p>To use the MicroStrain driver:</p><ol><li><p>Include the module in firmware in the <a href="./../hardware/porting_guide_config#px4-board-configuration-kconfig">kconfig board configuration</a> by setting the kconfig variables: <code>CONFIG_DRIVERS_INS_MICROSTRAIN</code> or <code>CONFIG_COMMON_INS</code>.</p></li><li><p>Configure the driver mode by setting <a href="./../advanced_config/parameter_reference#MS_MODE">MS_MODE</a></p><ul><li>To use the MicroStrain sensor to provide raw IMU data to EKF2 <ol><li><p>Set <a href="./../advanced_config/parameter_reference#MS_MODE">MS_MODE</a> to 0</p></li><li><p>Update the <a href="./../advanced_config/parameter_reference#EKF2_MULTI_IMU">EKF2_MULTI_IMU</a> parameter to account for the added MicroStrain sensor.</p></li><li><p>Enable EKF2 by setting <a href="./../advanced_config/parameter_reference#EKF2_EN">EKF2_EN</a> to 1</p></li><li><p>To prioritize MicroStrain sensor output, adjust the priority level of individual sensors from 0-100 using the following parameters:</p><ul><li><a href="./../advanced_config/parameter_reference#CAL_ACC0_PRIO">CAL_ACCn_PRIO</a></li><li><a href="./../advanced_config/parameter_reference#CAL_GYRO0_PRIO">CAL_GYROn_PRIO</a></li><li><a href="./../advanced_config/parameter_reference#CAL_MAG0_PRIO">CAL_MAGn_PRIO</a></li><li><a href="./../advanced_config/parameter_reference#CAL_BARO0_PRIO">CAL_BAROn_PRIO</a></li></ul><p>where <code>n</code> corresponds to the index of the corresponding sensor.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Sensors can be identified by their device id, which can be found by checking the parameters:</p><ul><li><a href="./../advanced_config/parameter_reference#CAL_ACC0_ID">CAL_ACCn_ID</a></li><li><a href="./../advanced_config/parameter_reference#CAL_GYRO0_ID">CAL_GYROn_ID</a></li><li><a href="./../advanced_config/parameter_reference#CAL_MAG0_ID">CAL_MAGn_ID</a></li><li><a href="./../advanced_config/parameter_reference#CAL_BARO0_ID">CAL_BAROn_ID</a></li></ul></div></li></ol></li></ul></li></ol><p>:::</p><ul><li>To use the MicroStrain sensor as an external INS <ol><li>Set <a href="./../advanced_config/parameter_reference#MS_MODE">MS_MODE</a> to 1</li><li>Disable EKF2 by setting <a href="./../advanced_config/parameter_reference#EKF2_EN">EKF2_EN</a> to 0</li></ol></li></ul><ol start="3"><li>Reboot and start the driver <ul><li><code>microstrain start -d &lt;port&gt;</code></li><li>To start the driver automatically when the flight controller powers on, set <a href="./../advanced_config/parameter_reference#SENS_MS_CFG">SENS_MS_CFG</a> to the sensor’s connected port.</li></ul></li></ol><h2 id="microstrain-configuration" tabindex="-1">MicroStrain Configuration <a class="header-anchor" href="#microstrain-configuration" aria-label="Permalink to &quot;MicroStrain Configuration&quot;">​</a></h2><ol><li><p>Rates:</p><ul><li><p>By default, accel and gyro data are published at 500 Hz, magnetometer at 50 Hz, and barometric pressure at 50 Hz. This can be changed by adjusting the following parameters:</p><ul><li><a href="./../advanced_config/parameter_reference#MS_IMU_RATE_HZ">MS_IMU_RATE_HZ</a></li><li><a href="./../advanced_config/parameter_reference#MS_MAG_RATE_HZ">MS_MAG_RATE_HZ</a></li><li><a href="./../advanced_config/parameter_reference#MS_BARO_RATE_HZ">MS_BARO_RATE_HZ</a></li></ul></li><li><p>Global position, local position, attitude and odometry will be published at 250 Hz by default. This can be configured via:</p><ul><li><a href="./../advanced_config/parameter_reference#MS_FILT_RATE_HZ">MS_FILT_RATE_HZ</a></li></ul></li><li><p>For the CV7-GNSS/INS, the GNSS receiver 1 and 2 will publish data at 5Hz by default. This can be changed using:</p><ul><li><a href="./../advanced_config/parameter_reference#MS_GNSS_RATE_HZ">MS_GNSS_RATE_HZ</a></li></ul></li><li><p>The driver will automatically configure data outputs based on the specific sensor model and available data streams.</p></li><li><p>The driver is scheduled to run at twice the fastest configured data rate.</p></li></ul></li><li><p>Aiding measurements:</p><ul><li><p>If supported, GNSS position and velocity aiding are always enabled.</p></li><li><p>Internal/external magnetometer and heading aiding, as well as optical flow aiding, are disabled by default. They can be enabled using the following parameters:</p><ul><li><a href="./../advanced_config/parameter_reference#MS_INT_MAG_EN">MS_INT_MAG_EN</a></li><li><a href="./../advanced_config/parameter_reference#MS_INT_HEAD_EN">MS_INT_HEAD_EN</a></li><li><a href="./../advanced_config/parameter_reference#MS_EXT_HEAD_EN">MS_EXT_HEAD_EN</a></li><li><a href="./../advanced_config/parameter_reference#MS_EXT_MAG_EN">MS_EXT_MAG_EN</a></li><li><a href="./../advanced_config/parameter_reference#MS_OPT_FLOW_EN">MS_OPT_FLOW_EN</a></li></ul></li><li><p>The aiding frames for external sources can be configured using the following parameters:</p><ul><li><a href="./../advanced_config/parameter_reference#MS_EHEAD_YAW">MS_EHEAD_YAW</a></li><li><a href="./../advanced_config/parameter_reference#MS_EMAG_ROLL">MS_EMAG_ROLL</a></li><li><a href="./../advanced_config/parameter_reference#MS_EMAG_PTCH">MS_EMAG_PTCH</a></li><li><a href="./../advanced_config/parameter_reference#MS_EMAG_YAW">MS_EMAG_YAW</a></li><li><a href="./../advanced_config/parameter_reference#MS_OFLW_OFF_X">MS_OFLW_OFF_X</a></li><li><a href="./../advanced_config/parameter_reference#MS_OFLW_OFF_Y">MS_OFLW_OFF_Y</a></li><li><a href="./../advanced_config/parameter_reference#MS_OFLW_OFF_Z">MS_OFLW_OFF_Z</a></li><li><a href="./../advanced_config/parameter_reference#SENS_FLOW_ROT">SENS_FLOW_ROT</a></li></ul></li><li><p>The uncertainty for optical flow and external magnetometer aiding must be specified using the following parameters:</p><ul><li><a href="./../advanced_config/parameter_reference#MS_EMAG_UNCERT">MS_EMAG_UNCERT</a></li><li><a href="./../advanced_config/parameter_reference#MS_OFLW_UNCERT">MS_OFLW_UNCERT</a></li></ul></li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><ol><li>When optical flow aiding is enabled, the sensor uses the <code>vehicle_optical_flow_vel</code> output from the flight controller as a body-frame velocity aiding measurement.</li><li>If the MicroStrain sensor does not support these aiding sources but they are enabled, sensor initialization will fail.</li></ol></div></li></ol><p>:::</p><ol start="3"><li><p>Initial heading alignment:</p><ul><li>Initial heading alignment is set to kinematic by default. This can be changed by adjusting <ul><li><a href="./../advanced_config/parameter_reference#MS_ALIGNMENT">MS_ALIGNMENT</a></li></ul></li></ul></li><li><p>GNSS Aiding Source Control (GNSS/INS only)</p><ul><li>The Source of the GNSS aiding data can be configured using: <ul><li><a href="./../advanced_config/parameter_reference#MS_GNSS_AID_SRC">MS_GNSS_AID_SRC</a></li></ul></li></ul></li><li><p>Sensor to vehicle transform:</p><ul><li><p>If the sensor is mounted in an orientation different from the vehicle frame. A sensor to vehicle transform can be enabled using</p><ul><li><a href="./../advanced_config/parameter_reference#MS_SVT_EN">MS_SVT_EN</a></li></ul></li><li><p>The transform is defined using the following parameters</p><ul><li><a href="./../advanced_config/parameter_reference#MS_SENSOR_ROLL">MS_SENSOR_ROLL</a></li><li><a href="./../advanced_config/parameter_reference#MS_SENSOR_PTCH">MS_SENSOR_PTCH</a></li><li><a href="./../advanced_config/parameter_reference#MS_SENSOR_YAW">MS_SENSOR_YAW</a></li></ul></li></ul></li><li><p>IMU ranges:</p><ul><li>The accelerometer and gyroscope ranges on the device are configurable using: <ul><li><a href="./../advanced_config/parameter_reference#MS_ACCEL_RANGE">MS_ACCEL_RANGE</a></li><li><a href="./../advanced_config/parameter_reference#MS_GYRO_RANGE">MS_GYRO_RANGE</a></li></ul></li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Available range settings depend on the specific <a href="https://www.hbkworld.com/en/products/transducers/inertial-sensors" target="_blank" rel="noreferrer">sensor</a> and can be found in the corresponding user manual. By default, the ranges are not changed.</p></div></li></ol><p>:::</p><ol start="7"><li>GNSS Lever arm offsets: <ul><li><p>The lever arm offset for the external GNSS receiver can be configured using:</p><ul><li><a href="./../advanced_config/parameter_reference#MS_GNSS_OFF1_X">MS_GNSS_OFF1_X</a></li><li><a href="./../advanced_config/parameter_reference#MS_GNSS_OFF1_Y">MS_GNSS_OFF1_Y</a></li><li><a href="./../advanced_config/parameter_reference#MS_GNSS_OFF1_Z">MS_GNSS_OFF1_Z</a></li></ul></li><li><p>For dual-antenna configurations, the second GNSS receiver’s offset is configured using:</p><ul><li><a href="./../advanced_config/parameter_reference#MS_GNSS_OFF2_X">MS_GNSS_OFF2_X</a></li><li><a href="./../advanced_config/parameter_reference#MS_GNSS_OFF2_Y">MS_GNSS_OFF2_Y</a></li><li><a href="./../advanced_config/parameter_reference#MS_GNSS_OFF2_Z">MS_GNSS_OFF2_Z</a></li></ul></li></ul></li></ol><h2 id="published-data" tabindex="-1">Published Data <a class="header-anchor" href="#published-data" aria-label="Permalink to &quot;Published Data&quot;">​</a></h2><p>The MicroStrain driver continuously publishes sensor data to the following uORB topics:</p><ul><li><a href="./../msg_docs/SensorAccel">sensor_accel</a></li><li><a href="./../msg_docs/SensorGyro">sensor_gyro</a></li><li><a href="./../msg_docs/SensorMag">sensor_mag</a></li><li><a href="./../msg_docs/SensorBaro">sensor_baro</a></li></ul><p>For GNSS/INS devices, GPS data is also published to:</p><ul><li><a href="./../msg_docs/SensorGps">sensor_gps</a></li></ul><p>If used as an external INS replacing EKF2, it publishes:</p><ul><li><a href="./../msg_docs/VehicleGlobalPosition">vehicle_global_position</a></li><li><a href="./../msg_docs/VehicleLocalPosition">vehicle_local_position</a></li><li><a href="./../msg_docs/VehicleAttitude">vehicle_attitude</a></li><li><a href="./../msg_docs/VehicleOdometry">vehicle_odometry</a></li></ul><p>otherwise the same data is published to the following topics</p><ul><li><code>external_ins_global_position</code></li><li><code>external_ins_attitude</code></li><li><code>external_ins_local_position</code></li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Published topics can be viewed using the <code>listener</code> command.</p></div>',36)])])}const S=r(o,[["render",l]]);export{u as __pageData,S as default};
